function validate([differences, lower, upper]) {
  if (!Array.isArray(differences) || differences.length < 1 || differences.length > 100000) return 'differences needs 1 to 10^5 values.';
  if (differences.some(d => !Number.isInteger(d) || d < -100000 || d > 100000)) return 'Each difference is an integer between -10^5 and 10^5.';
  if (!Number.isInteger(lower) || !Number.isInteger(upper)) return 'lower and upper are integers.';
  if (lower < -100000 || upper > 100000) return 'lower and upper lie between -10^5 and 10^5.';
  if (lower > upper) return 'lower must not exceed upper.';
  return null;
}

