function numberOfArrays(differences, lower, upper) {
  let current = 0;
  let lowest = 0;
  let highest = 0;

  for (const step of differences) {
    current += step;
    lowest = Math.min(lowest, current);
    highest = Math.max(highest, current);
  }

  const span = highest - lowest;
  return Math.max(0, upper - lower - span + 1);
}

