function numberOfArrays(differences, lower, upper) {
  let count = 0;
  for (let first = lower; first <= upper; first++) {
    let value = first;
    let fits = true;
    for (const d of differences) {
      value += d;
      if (value < lower || value > upper) { fits = false; break; }
    }
    if (fits) count++;
  }
  return count;
}

