function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 6);
    const reach = int(0, 6);
    const differences = Array.from({ length: n }, () => int(-reach, reach));
    const lower = int(-12, 12);
    const upper = lower + int(0, 18);
    return [differences, lower, upper];
  }
  const n = 2000;
  const reach = [1, 40, 1500, 100000][int(0, 3)];
  const differences = Array.from({ length: n }, () => int(-reach, reach));
  const lower = int(-100000, 0);
  const upper = int(Math.max(lower, -20000), 100000);
  return [differences, lower, upper];
}
